// El cuerpo de un correo trae firmas, cadenas de respuestas y HTML. Se recorta
// lo evidente y se acota: `BYTE_MAX_MESSAGE_CHARS` son 8000 por defecto, y un
// hilo largo los pasa fácil.
const LIMITE = 7000;

for (const item of $input.all()) {
  let texto = item.json.textPlain || item.json.text || '';

  // Corta la cadena de respuestas: lo de abajo ya lo leyó quien escribió.
  const marcas = [/^>.*/m, /^-{2,}\s*$/m, /^El .* escribió:/m, /^On .* wrote:/m];
  for (const marca of marcas) {
    const donde = texto.search(marca);
    if (donde > 40) texto = texto.slice(0, donde);
  }

  texto = texto.replace(/\n{3,}/g, '\n\n').trim().slice(0, LIMITE);

  item.json.pregunta = texto;
  item.json.responder_a = item.json.from;
  item.json.asunto = item.json.subject || '(sin asunto)';
}

return $input.all();

